const BASE = 'https://raw.githubusercontent.com/abhinav-genacademy/n8n-projects-week-2/refs/heads/main/';

const docs = [
  { FILE_URL: BASE + 'nexgen_10k_2024.txt',              label: 'NexGen 10-K Annual Report 2024' },
  { FILE_URL: BASE + 'nexgen_q3_2024_earnings_call.txt', label: 'NexGen Q3 2024 Earnings Call Transcript' },
  { FILE_URL: BASE + 'nexgen_credit_agreement_2024.txt', label: 'NexGen Credit Agreement 2024' }
];

return docs.map(d => ({ json: d }));

// ── BM25-STYLE SPARSE VECTOR BUILDER ───────────────────────────────────────
// Replaces the old HuggingFace embedding approach for the keyword branch.
// True keyword search: no neural network, no semantic similarity.
// Each token maps to a sparse dimension via FNV-1a hash; value = TF score.
//
// Output: one item per batch of ≤100 vectors (Pinecone upsert limit).
// ────────────────────────────────────────────────────────────────────────────

const text = $json.content;
const label = $json.label;
const CHUNK_SIZE = 500;
const CHUNK_OVERLAP = 100;
const MAX_SPARSE_DIM = 30000;

const STOPWORDS = new Set([
  'the','a','an','and','or','but','in','on','at','to','for','of',
  'with','by','from','is','are','was','were','be','been','have','has',
  'had','do','does','did','will','would','could','should','that','this',
  'it','as','not','if','they','we','you','he','she','i','its','about'
]);

// Split into overlapping chunks
const chunks = [];
let start = 0;
while (start < text.length) {
  const end = Math.min(start + CHUNK_SIZE, text.length);
  chunks.push(text.slice(start, end));
  if (end === text.length) break;
  start += CHUNK_SIZE - CHUNK_OVERLAP;
}

// FNV-1a hash: token string → stable non-negative integer (sparse dimension)
function fnv1a(str) {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h % MAX_SPARSE_DIM;
}

// Build one sparse vector per chunk
const vectors = chunks.map((chunk, i) => {
  const tokens = chunk.toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(t => t.length > 2 && !STOPWORDS.has(t));

  const tf = {};
  for (const t of tokens) tf[t] = (tf[t] || 0) + 1;

  const maxFreq = Math.max(1, ...Object.values(tf));
  const seenIdx = new Set();
  const indices = [];
  const values = [];

  for (const [token, freq] of Object.entries(tf)) {
    const idx = fnv1a(token);
    if (!seenIdx.has(idx)) {  // skip hash collisions (keep first)
      seenIdx.add(idx);
      indices.push(idx);
      values.push(parseFloat((freq / maxFreq).toFixed(4)));
    }
  }

  return {
    id: `kw-${label.replace(/[^a-z0-9]/gi, '-').toLowerCase()}-${i}`,
    values: new Array(384).fill(1e-7),
    sparseValues: { indices, values },
    metadata: { text: chunk, label, strategy: 'keyword', chunk_index: i }
  };
}).filter(v => v.sparseValues.indices.length > 0);

// Batch into groups of 100 for Pinecone upsert limit
const batches = [];
for (let i = 0; i < vectors.length; i += 100) {
  batches.push({ json: { vectors: vectors.slice(i, i + 100) } });
}
return batches;
